const $=s=>document.querySelector(s),app=$('#app'),mr=$('#modal-root');let state=null,publicData=null,section='orders',view='board',query='',filters={status:'',manager:'',course:'',paid:'',from:'',to:''},taskTab='all',showArchive=false;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const money=v=>new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB',maximumFractionDigits:0}).format(v/100);const date=v=>new Date(v).toLocaleString('ru-RU',{timeZone:'Europe/Moscow',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'});const today=()=>new Date().toLocaleDateString('sv-SE',{timeZone:'Europe/Moscow'});const image=(id,w=1000)=>`https://images.unsplash.com/${id}?auto=format&fit=crop&w=${w}&q=85`;const icons={orders:'▦',clients:'♧',tasks:'✓',courses:'▤',analytics:'◴',employees:'♙'};const labels={orders:'Заказы',clients:'Клиенты',tasks:'Задачи',courses:'Курсы',analytics:'Аналитика',employees:'Сотрудники'};
async function api(path,body){let r=await fetch('/api/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});let d=await r.json();if(!r.ok)throw Error(d.error);return d}function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function modal(html,wide=false){mr.innerHTML=`<div class="veil"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="Подробности"><button class="close" data-action="close" aria-label="Закрыть">×</button>${html}</section></div>`;document.body.classList.add('locked');setTimeout(()=>mr.querySelector('input,button,select')?.focus(),0)}function close(){mr.innerHTML='';document.body.classList.remove('locked')}function formData(f){return Object.fromEntries(new FormData(f))}function permitted(k,write=false){return state?.user.role==='admin'||Number(state?.user.permissions[k])>=(write?2:1)}function userName(id){return state.users.find(u=>u.id===id)?.name||'Не назначен'}function client(o){return state.clients.find(c=>c.id===o.clientId)||{name:'Клиент',email:''}}function course(o){return state.courses.find(c=>c.id===o.courseId)||{title:'Курс'}}
function site(){app.innerHTML=`<div class="site editorial"><header class="site-header"><a class="brand" href="#" aria-label="NUTRIA, на главную">nutria<span><svg class="leaf-mark" viewBox="0 0 40 40" aria-hidden="true" focusable="false"><path d="M19 33C7 33 2 25 3 13c12-1 21 7 16 20Z" opacity=".75"/><path d="M22 26C16 13 24 4 37 3c1 13-4 23-15 23Z"/><path d="m12 23 12 13m-4-7 10-15" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg></span></a><span class="brand-caption">Школа питания<br>для настоящей жизни</span><nav><a href="#courses">Программы</a><a href="#approach">Философия</a><a href="#teachers">Команда</a></nav><button class="btn outline" data-action="login">Демо CRM <span>↗</span></button></header><main><section class="hero"><div class="hero-copy"><div class="quiet-label"><span class="small-leaf"><svg class="leaf-mark" viewBox="0 0 40 40" aria-hidden="true" focusable="false"><path d="M19 33C7 33 2 25 3 13c12-1 21 7 16 20Z" opacity=".75"/><path d="M22 26C16 13 24 4 37 3c1 13-4 23-15 23Z"/><path d="m12 23 12 13m-4-7 10-15" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg></span> Еда. Знания. Хорошие привычки.</div><h1>Есть вкусно.<br>Жить ярко.</h1><p>Здоровые отношения с едой начинаются с интереса. Открывайте новое, пробуйте любимое и находите свой ритм — вместе с NUTRIA.</p><div class="hero-actions"><a class="btn primary" href="#courses">Найти свою программу <span>↗</span></a><a class="hero-link" href="#approach">Познакомиться со школой <span>↓</span></a></div><div class="hero-caption"><span class="caption-line"></span><p>Не очередная диета.<br>Новый взгляд на привычное.</p></div></div><div class="hero-photo"><img src="${image('photo-1511690743698-d9d85f2fbf38',1400)}" alt="Яркая тарелка с авокадо, овощами и лососем" fetchpriority="high"><div class="hero-photo-shade"></div><span class="photo-caption">Ваша тарелка. Ваши правила.</span><button class="hero-course" data-action="course" data-id="1"><span class="hero-course-thumb"><img src="${image('photo-1490645935967-10de6ba17061',350)}" alt="Свежие продукты для курса"></span><span><small>Начните с простого</small><strong>Питание с нуля</strong><em>4 недели · ${money(publicData.courses[0].price)}</em></span><span class="circle-arrow">↗</span></button></div><div class="hero-bottom-label"><span>Маленькие шаги. Большая разница.</span><span>Листайте — будет вкусно ↓</span></div></section><section class="values-strip" aria-label="Наши ценности"><div class="values-track">${[0,1].map(i=>`<div ${i?'aria-hidden="true"':''}><span>Больше разнообразия</span><i><svg class="leaf-mark" viewBox="0 0 40 40" aria-hidden="true" focusable="false"><path d="M19 33C7 33 2 25 3 13c12-1 21 7 16 20Z" opacity=".75"/><path d="M22 26C16 13 24 4 37 3c1 13-4 23-15 23Z"/><path d="m12 23 12 13m-4-7 10-15" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg></i><span>Меньше ограничений</span><i><svg class="leaf-mark" viewBox="0 0 40 40" aria-hidden="true" focusable="false"><path d="M19 33C7 33 2 25 3 13c12-1 21 7 16 20Z" opacity=".75"/><path d="M22 26C16 13 24 4 37 3c1 13-4 23-15 23Z"/><path d="m12 23 12 13m-4-7 10-15" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg></i><span>В своём ритме</span><i><svg class="leaf-mark" viewBox="0 0 40 40" aria-hidden="true" focusable="false"><path d="M19 33C7 33 2 25 3 13c12-1 21 7 16 20Z" opacity=".75"/><path d="M22 26C16 13 24 4 37 3c1 13-4 23-15 23Z"/><path d="m12 23 12 13m-4-7 10-15" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg></i><span>С удовольствием</span><i><svg class="leaf-mark" viewBox="0 0 40 40" aria-hidden="true" focusable="false"><path d="M19 33C7 33 2 25 3 13c12-1 21 7 16 20Z" opacity=".75"/><path d="M22 26C16 13 24 4 37 3c1 13-4 23-15 23Z"/><path d="m12 23 12 13m-4-7 10-15" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg></i></div>`).join('')}</div></section><section id="courses" class="section courses-section"><div class="section-heading"><div><div class="quiet-label">Программы NUTRIA</div><h2>Что добавим<br>в вашу жизнь?</h2></div><p>Знания, которые не останутся в конспекте.<br>Четыре программы — найдите свою.</p><span class="section-flower" aria-hidden="true"><svg class="leaf-mark" viewBox="0 0 40 40" aria-hidden="true" focusable="false"><path d="M19 33C7 33 2 25 3 13c12-1 21 7 16 20Z" opacity=".75"/><path d="M22 26C16 13 24 4 37 3c1 13-4 23-15 23Z"/><path d="m12 23 12 13m-4-7 10-15" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg></span></div><div class="course-grid">${publicData.courses.map((c,i)=>`<article class="course-card course-${i}"><button class="course-image" data-action="course" data-id="${c.id}"><img src="${image(c.image,i===0?1200:800)}" alt="${esc(c.title)}" loading="lazy"><span class="pill">${i===0?'Идеальная точка старта':esc(c.category)}</span><span class="image-arrow">↗</span><span class="course-photo-caption">${['Понять свою тарелку','Освободить время для жизни','Собираться за одним столом','Найти баланс без запретов'][i]}</span></button><div class="course-info"><div class="course-meta"><span>${c.weeks} ${c.weeks===4?'недели':'недель'}</span><span>${['Основы питания','С поддержкой куратора','Семейный рацион','Практика и встречи'][i]}</span></div><h3><button data-action="course" data-id="${c.id}">${esc(c.title)}</button></h3><p>${esc(c.short)}</p><div class="course-bottom"><strong>${money(c.price)}</strong><button class="text-button" data-action="course" data-id="${c.id}">Подробнее о программе <span>↗</span></button></div></div></article>`).join('')}</div></section><section id="approach" class="approach section"><div class="approach-visual"><img src="${image('photo-1490645935967-10de6ba17061',1200)}" alt="Разнообразие свежих продуктов на столе" loading="lazy"><div class="approach-tag">Всё начинается<br>с любопытства.</div></div><div class="approach-copy"><div class="quiet-label">Наша философия</div><h2>У жизни нет<br>идеального меню.</h2><p class="large-text">Зато есть еда, которая нравится. Ритм, который подходит. И знания, с которыми проще выбирать.</p><div class="principle"><span><svg class="leaf-mark" viewBox="0 0 40 40" aria-hidden="true" focusable="false"><path d="M19 33C7 33 2 25 3 13c12-1 21 7 16 20Z" opacity=".75"/><path d="M22 26C16 13 24 4 37 3c1 13-4 23-15 23Z"/><path d="m12 23 12 13m-4-7 10-15" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg></span><div><h3>Разбираться, а не запрещать</h3><p>Понятно объясняем основы на знакомых продуктах. Никаких списков «плохой еды».</p></div></div><div class="principle"><span><svg class="leaf-mark" viewBox="0 0 40 40" aria-hidden="true" focusable="false"><path d="M19 33C7 33 2 25 3 13c12-1 21 7 16 20Z" opacity=".75"/><path d="M22 26C16 13 24 4 37 3c1 13-4 23-15 23Z"/><path d="m12 23 12 13m-4-7 10-15" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg></span><div><h3>Пробовать, а не быть идеальным</h3><p>Небольшие практики на своей кухне. Привычки, которым найдётся место в обычном дне.</p></div></div><div class="principle"><span><svg class="leaf-mark" viewBox="0 0 40 40" aria-hidden="true" focusable="false"><path d="M19 33C7 33 2 25 3 13c12-1 21 7 16 20Z" opacity=".75"/><path d="M22 26C16 13 24 4 37 3c1 13-4 23-15 23Z"/><path d="m12 23 12 13m-4-7 10-15" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg></span><div><h3>Выбирать свой ритм</h3><p>Учитываем работу, семью и любимые блюда. Учимся заботиться о себе без крайностей.</p></div></div><a href="#courses" class="btn light">Найти свою точку старта <span>↗</span></a></div></section><section class="learning section"><div class="section-heading"><div><div class="quiet-label">Так устроено обучение</div><h2>Из урока —<br>в обычный вторник.</h2></div><p>Никакой гонки за идеальным результатом.<br>Понятные шаги, которые можно повторить.</p></div><div class="steps"><article><span>1</span><h3>Сначала — интерес</h3><p>Выберите задачу: понять основы, наладить рацион или исследовать привычки.</p></article><article><span>2</span><h3>Потом — практика</h3><p>Короткий урок, новая идея и простое действие в магазине или на своей кухне.</p></article><article><span>3</span><h3>И свой способ жить</h3><p>Соберите подходящие вам решения. Возвращайтесь к материалам в своём темпе.</p></article></div><div class="learning-note"><span><svg class="leaf-mark" viewBox="0 0 40 40" aria-hidden="true" focusable="false"><path d="M19 33C7 33 2 25 3 13c12-1 21 7 16 20Z" opacity=".75"/><path d="M22 26C16 13 24 4 37 3c1 13-4 23-15 23Z"/><path d="m12 23 12 13m-4-7 10-15" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg></span><p>Самое полезное знание —<br>то, которое стало частью дня.</p></div></section><section id="teachers" class="section teachers-section"><div class="section-heading"><div><div class="quiet-label">На одной волне</div><h2>Знакомьтесь.<br>Ваши проводники.</h2></div><p>Объясняют сложное, поддерживают в практике<br>и тоже иногда заказывают пиццу.</p></div><div class="teacher-grid">${[['Мария Волкова','Основы питания','photo-1580489944761-15a19d654956'],['Елена Миронова','Практика и сопровождение','photo-1494790108377-be9c29b29330'],['Ирина Лебедева','Пищевые привычки','photo-1544005313-94ddf0286df2']].map(([n,r,i])=>`<article><div class="teacher-photo"><img src="${image(i,700)}" alt="Иллюстрация профиля преподавателя" loading="lazy"><span>Познакомимся на курсе ↗</span></div><div class="teacher-caption"><h3>${n}</h3><span><svg class="leaf-mark" viewBox="0 0 40 40" aria-hidden="true" focusable="false"><path d="M19 33C7 33 2 25 3 13c12-1 21 7 16 20Z" opacity=".75"/><path d="M22 26C16 13 24 4 37 3c1 13-4 23-15 23Z"/><path d="m12 23 12 13m-4-7 10-15" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg></span></div><p>${r}</p></article>`).join('')}</div><p class="illustration-note">Демонстрационные профили команды. Фотографии служат иллюстрациями.</p></section><section class="review section"><div class="review-label">Из дневника перемен</div><div class="review-body"><span class="quote">“</span><blockquote>Раньше я думала,<br>что нужно всё поменять.<br>Оказалось — можно<br>просто начать.</blockquote><p>Александра, курс «Рацион без хаоса»<br><small>Демонстрационный отзыв</small></p></div><div class="review-photo"><img src="${image('photo-1547592180-85f173990554',800)}" alt="Свежий салат, приготовленный дома" loading="lazy"><span>Место для новых привычек.</span></div></section><section id="faq" class="section faq"><div><div class="quiet-label">Всё можно спросить</div><h2>Любопытство<br>приветствуется.</h2><p>Несколько ответов перед началом.</p></div><div>${[['Можно начать без подготовки?','Конечно. Программы рассчитаны на взрослых без специальных знаний. Если хочется разобраться в основах, начните с курса «Сбалансированное питание с нуля».'],['Как устроено обучение?','Короткие видеоуроки, материалы и практика в удобное время. Поддержка куратора и групповые встречи зависят от выбранной программы.'],['Придётся отказываться от любимой еды?','В программах нет универсальных списков запрещённых продуктов. Мы изучаем общие принципы, разнообразие и привычки. Курсы не заменяют консультацию врача.'],['Как попробовать покупку курса?','Это демонстрационная школа. Вы можете создать заказ, проверить имитацию оплаты и увидеть заявку в CRM. Деньги не списываются, настоящего обучения нет.']].map(([q,a])=>`<details><summary>${q}<span>+</span></summary><p>${a}</p></details>`).join('')}</div></section><section class="final-cta"><div class="cta-intro">Любопытно, что получится?</div><div class="cta-main"><h2>Начнём<br>с вашей тарелки.</h2><a class="btn light" href="#courses">Выбрать программу <span>↗</span></a></div><span class="cta-flower" aria-hidden="true"><svg class="leaf-mark" viewBox="0 0 40 40" aria-hidden="true" focusable="false"><path d="M19 33C7 33 2 25 3 13c12-1 21 7 16 20Z" opacity=".75"/><path d="M22 26C16 13 24 4 37 3c1 13-4 23-15 23Z"/><path d="m12 23 12 13m-4-7 10-15" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg></span><p>Маленькое решение сегодня.<br>Новая привычка завтра.</p></section></main><footer><a class="brand" href="#">nutria<span><svg class="leaf-mark" viewBox="0 0 40 40" aria-hidden="true" focusable="false"><path d="M19 33C7 33 2 25 3 13c12-1 21 7 16 20Z" opacity=".75"/><path d="M22 26C16 13 24 4 37 3c1 13-4 23-15 23Z"/><path d="m12 23 12 13m-4-7 10-15" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg></span></a><p>Больше жизни.<br>Больше вкуса.</p><div><a href="mailto:hello@example.com">hello@example.com</a><button data-action="login">Открыть демо CRM ↗</button></div><small>© 2026 NUTRIA. Демонстрация для портфолио. Курсы, команда и отзывы вымышлены. Реальные платежи отсутствуют.</small></footer></div>`;enhanceSite()}
function enhanceSite(){const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;if(!reduced){const observer=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){entry.target.classList.add('in-view');observer.unobserve(entry.target)}},{threshold:.12});app.querySelectorAll('.section-heading,.course-card,.approach-visual,.approach-copy,.steps article,.teacher-grid article,.review-body,.review-photo,.faq>div,.cta-main').forEach(el=>{el.classList.add('reveal');observer.observe(el)});app.querySelectorAll('.course-image,.hero-photo').forEach(el=>{el.addEventListener('pointermove',e=>{if(e.pointerType!=='mouse')return;const r=el.getBoundingClientRect();el.style.setProperty('--pointer-x',`${(e.clientX-r.left-r.width/2)*.015}px`);el.style.setProperty('--pointer-y',`${(e.clientY-r.top-r.height/2)*.015}px`)});el.addEventListener('pointerleave',()=>{el.style.setProperty('--pointer-x','0px');el.style.setProperty('--pointer-y','0px')})})}}

const coursePrograms={
1:{author:'Мария Волкова',materials:'4 тематических модуля, видеоуроки, конспект по основам питания, памятка по этикеткам и конструктор сбалансированной тарелки.',modules:[
['Знакомимся со своей тарелкой','Разбираем разнообразие рациона и роль регулярного питания. Учимся замечать, из чего складываются привычные завтраки, обеды и ужины.','Составьте карту своего питания за три обычных дня и выберите, что хочется разнообразить.'],
['Белки, жиры, углеводы — без путаницы','Изучаем основные группы питательных веществ и их источники в повседневных продуктах. Знакомимся с ролью клетчатки и питьевыми привычками.','Подберите несколько доступных источников белка, жиров и углеводов из продуктов, которые вам нравятся.'],
['Что на самом деле написано на упаковке','Учимся читать состав и пищевую ценность, сравнивать продукты одной категории и отличать полезную информацию от рекламных обещаний.','Сравните этикетки трёх продуктов из своей корзины и объясните свой выбор.'],
['Собираем рацион из любимой еды','Используем принцип сбалансированной тарелки, добавляем разнообразие и подбираем сочетания под свой распорядок.','Соберите три варианта завтрака, обеда и ужина и составьте свой план небольших изменений.']
]},
2:{author:'Елена Миронова',materials:'6 практических модулей, сопровождение куратора, шаблон недельного меню, список покупок, карта хранения и план заготовок.',modules:[
['Где теряется время на еду','Разбираем ваш график, загрузку кухни и повторяющиеся сложности: пропущенные покупки, внезапные ужины и продукты без назначения.','Отметьте занятые дни недели и составьте карту ситуаций, для которых нужен готовый план.'],
['Конструктор меню на неделю','Планируем не семь разных сложных ужинов, а сочетания базовых продуктов. Учитываем остатки, повторение блюд и дни без готовки.','Составьте гибкое меню на неделю с двумя запасными вариантами.'],
['Покупки по делу','Собираем список по меню, проверяем домашние запасы, сравниваем стоимость и выбираем подходящий ритм закупок.','Подготовьте список одной основной закупки и короткого пополнения в середине недели.'],
['Заготовки за один подход','Планируем параллельное приготовление круп, овощей и основных компонентов. Разбираем порядок работы, хранение и маркировку заготовок.','Составьте пошаговый план кухонной сессии и приготовьте компоненты для нескольких блюд.'],
['Быстрые сборки и план Б','Превращаем заготовки в разные блюда. Продумываем решения для позднего возвращения домой, еды с собой и заказа доставки.','Соберите пять вариантов еды за 15 минут и свой список запасных решений.'],
['Система, которая выдержит обычную неделю','Проверяем меню в реальной жизни, обсуждаем с куратором неудобные места и сокращаем лишние действия.','Протестируйте систему в течение недели и сохраните рабочий шаблон меню, закупок и готовки.']
]},
3:{author:'Елена Миронова',materials:'5 модулей, семейный планировщик меню, таблица предпочтений, подборка блюд с вариациями и памятка по совместной готовке.',modules:[
['Разные вкусы за одним столом','Собираем предпочтения и расписания домашних. Учимся обсуждать еду без давления и искать общую основу семейного меню.','Создайте семейную карту любимых продуктов, удобного времени еды и бытовых ограничений.'],
['Одна основа — несколько вариантов','Разбираем блюда-конструкторы: общую основу можно дополнить разными соусами, гарнирами и добавками.','Подберите четыре семейных блюда и придумайте варианты подачи под разные вкусы.'],
['Завтраки, перекусы и еда с собой','Планируем удобные решения для утра, работы, учёбы и совместных поездок. Обсуждаем упаковку, хранение и разнообразие.','Составьте пять вариантов завтрака и три набора еды с собой для своей семьи.'],
['Готовим вместе и знакомимся с новым','Распределяем кухонные задачи с учётом возраста и возможностей. Пробуем новые продукты без принуждения и сохраняем знакомую еду на столе.','Организуйте совместное приготовление одного блюда и дегустацию нового продукта по желанию участников.'],
['Семейное меню без второй смены','Соединяем предпочтения, бюджет и время в общий план. Упрощаем покупки и договариваемся о распределении домашних дел.','Подготовьте недельное меню, общий список покупок и удобный график участия в готовке.']
]},
4:{author:'Ирина Лебедева',materials:'8 модулей, дневник наблюдений без подсчёта калорий, аудиопрактики внимания, групповые встречи и личная карта привычек.',modules:[
['Наблюдаем без оценок','Знакомимся с устройством привычки: контекстом, действием и результатом. Учимся описывать свой опыт без деления на успехи и провалы.','Пять дней отмечайте обстоятельства приёмов пищи и свои ощущения без оценок и подсчёта калорий.'],
['Замечаем голод и насыщение','Исследуем телесные ощущения до, во время и после еды. Учимся делать паузу для наблюдения, сохраняя гибкость и регулярность питания.','Выберите один приём пищи в день и запишите, как меняются ощущения в процессе.'],
['Возвращаем вкус и внимание','Изучаем, как темп еды, экран и обстановка влияют на внимание к вкусу. Пробуем короткие сенсорные практики без требования есть «идеально».','Проведите дегустацию знакомого продукта, замечая аромат, текстуру и изменения вкуса.'],
['Эмоции и еда: замечаем связь','Разбираем бытовые ситуации, в которых еда связана с усталостью, скукой или напряжением. Ищем дополнительные способы заботы о себе, не запрещая еду.','Составьте личный список поддерживающих действий для нескольких знакомых ситуаций.'],
['Пищевые правила под вопросом','Исследуем усвоенные установки о «правильной» еде и язык самокритики. Учимся формулировать более гибкие и доброжелательные ориентиры.','Перепишите три жёстких правила в виде гибких решений, учитывающих ваши обстоятельства.'],
['Среда, которая поддерживает','Замечаем влияние расписания, доступности еды и кухонных привычек. Меняем обстановку так, чтобы подходящие решения требовали меньше усилий.','Выберите и проверьте два небольших изменения дома или на работе.'],
['Гибкость в гостях, поездках и занятых днях','Практикуем выбор в непривычных обстоятельствах. Обсуждаем, как возвращаться к привычному ритму без компенсаций и самонаказания.','Продумайте удобные решения для трёх предстоящих ситуаций вне обычного расписания.'],
['Своя карта устойчивых привычек','Подводим итоги наблюдений и групповых обсуждений. Выбираем работающие практики и реалистичный способ поддерживать их дальше.','Составьте план на месяц: две поддерживающие привычки, признаки перегрузки и способы упростить задачу.']
]}
};
function courseModal(id){let c=publicData.courses.find(c=>c.id===Number(id));if(!c)return;let program=coursePrograms[c.id];modal(`<img class="modal-cover" src="${image(c.image,1000)}" alt="${esc(c.title)}"><div class="quiet-label">${c.weeks} ${c.weeks===4?'недели':'недель'} · ${esc(c.category)}</div><h2>${esc(c.title)}</h2><p>${esc(c.desc)}</p><h3>Что будем изучать</h3><div class="modules">${program.modules.map(([title,description,practice],i)=>`<details ${i===0?'open':''}><summary>Модуль ${i+1}. ${esc(title)}</summary><p>${esc(description)}</p><p><strong>Практика:</strong> ${esc(practice)}</p></details>`).join('')}</div><h3>В программу входят</h3><p>${esc(program.materials)}</p><p>Автор программы — ${esc(program.author)}. Профиль вымышленный.</p><details><summary>Когда можно начать?</summary><p>В демо заказ создаётся сразу. Доступ к настоящей учебной платформе не предоставляется.</p></details><div class="modal-bottom"><strong>${money(c.price)}</strong><button class="btn primary" data-action="checkout" data-id="${c.id}">Купить курс ↗</button></div>`)}
function checkout(id){let c=publicData.courses.find(c=>c.id===Number(id));modal(`<div class="quiet-label">Демонстрационный заказ</div><h2>Ваш следующий шаг.</h2><div class="checkout-summary"><h3>${esc(c.title)}</h3><strong>${money(c.price)}</strong></div><p class="notice">Используйте вымышленные контакты. Списания денег не будет.</p><form data-form="checkout"><input type="hidden" name="courseId" value="${c.id}"><input type="hidden" name="key" value="${crypto.randomUUID()}"><label>Имя<input name="name" required maxlength="100" placeholder="Александра Иванова" autocomplete="name"></label><label>Email<input name="email" type="email" required placeholder="student@example.com" autocomplete="email"></label><label>Телефон <span class="muted">необязательно</span><input name="phone" type="tel" placeholder="+7 900 000 00 00"></label><label>Комментарий<textarea name="comment" placeholder="Что вы хотели бы узнать?"></textarea></label><label class="checkbox"><input type="checkbox" name="consent" required>Согласен на обработку введённых данных в рамках демонстрации</label><p class="form-error" role="alert"></p><button class="btn primary full" type="submit">Оформить демо-заказ</button></form>`)}
function login(){modal(`<div class="quiet-label">Рабочее пространство NUTRIA</div><h2>Добро пожаловать.</h2><p>Выберите роль и проверьте CRM в своём отдельном демо-пространстве.</p><div class="demo-roles">${[['admin','Администратор','Все разделы и управление сотрудниками'],['manager','Менеджер','Все заказы и работа с клиентами'],['limited','Менеджер · свои заказы','Только закреплённые клиенты и заказы']].map(([id,n,t])=>`<button data-action="demo" data-id="${id}"><span class="role-icon">${id==='admin'?'♙':'♧'}</span><span><strong>${n}</strong><small>${t}</small></span><span>↗</span></button>`).join('')}</div><details><summary>Войти по email и паролю</summary><form data-form="login"><label>Email<input name="email" type="email" required value="admin@example.com" autocomplete="username"></label><label>Пароль<input name="password" type="password" required value="NutriaDemo2026!" autocomplete="current-password"></label><small>Демо: admin / manager / limited @example.com<br>Пароль: NutriaDemo2026!</small><p class="form-error" role="alert"></p><button class="btn primary full">Войти</button></form></details><p class="muted small">Регистрации нет. Профили сотрудников создаёт администратор.</p>`)}
async function enter(){state=await api('state');close();renderCRM()}
function filteredOrders(){return state.orders.filter(o=>{let c=client(o),q=query.toLowerCase();return (!!o.archived===showArchive)&&(!q||[c.name,c.email,c.phone,o.id].join(' ').toLowerCase().includes(q))&&(filters.status===''||o.status===Number(filters.status))&&(!filters.manager||o.manager===filters.manager)&&(!filters.course||o.courseId===Number(filters.course))&&(filters.paid===''||o.paid===(filters.paid==='true'))&&(!filters.from||o.created.slice(0,10)>=filters.from)&&(!filters.to||o.created.slice(0,10)<=filters.to)})}
function options(items,selected){return items.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(selected)?'selected':''}>${esc(t)}</option>`).join('')}
function filtersHTML(){return `<div class="filters"><label class="search">⌕<input id="search" value="${esc(query)}" placeholder="Найти клиента или заказ" aria-label="Поиск заказов"></label><select data-filter="status" aria-label="Статус">${options([['','Все статусы'],...state.stages.map((s,i)=>[i,s])],filters.status)}</select><select data-filter="manager" aria-label="Ответственный">${options([['','Все менеджеры'],...state.users.map(u=>[u.id,u.name])],filters.manager)}</select><select data-filter="course" aria-label="Курс">${options([['','Все курсы'],...state.courses.map(c=>[c.id,c.title])],filters.course)}</select><select data-filter="paid" aria-label="Оплата">${options([['','Любая оплата'],['true','Оплачен'],['false','Не оплачен']],filters.paid)}</select><details class="date-filter"><summary>Период</summary><div><label>С<input type="date" data-filter="from" value="${filters.from}"></label><label>По<input type="date" data-filter="to" value="${filters.to}"></label></div></details><button class="icon-btn" data-action="clear-filters" title="Сбросить фильтры" aria-label="Сбросить фильтры">↺</button></div>`}
function orderCard(o){let c=client(o),t=state.tasks.find(t=>t.orderId===o.id&&!t.done);return `<article class="order-card" ${permitted('orders',true)?'draggable="true"':''} data-order="${o.id}"><button class="card-main" data-action="order" data-id="${o.id}"><span class="order-number">#${o.id}<span>${o.paid?'● Оплачен':'○ Не оплачен'}</span></span><h3>${esc(c.name)}</h3><p>${esc(course(o).title)}</p><strong>${money(o.amount)}</strong></button><div class="card-meta"><span class="avatar tiny">${esc(userName(o.manager).split(' ').map(x=>x[0]).join(''))}</span><span>${esc(userName(o.manager).split(' ')[0])}</span><span class="card-date">${new Date(o.created).toLocaleDateString('ru-RU',{timeZone:'Europe/Moscow',day:'2-digit',month:'short'})}</span></div>${t?`<div class="task-hint ${t.due<today()?'overdue':''}">◷ ${esc(t.title)}</div>`:''}</article>`}
function ordersHTML(){let list=filteredOrders();return `<div class="page-title"><div><div class="breadcrumb">Рабочее пространство / Продажи</div><h1>Заказы <span class="count">${list.length}</span></h1><p>От первого знакомства до начала обучения.</p></div><div class="title-actions">${state.user.role==='admin'?`<button class="btn outline" data-action="archive-view">${showArchive?'Активные':'Архив'}</button>`:''}<div class="switch"><button class="${view==='board'?'active':''}" data-action="view" data-id="board">▦ Доска</button><button class="${view==='table'?'active':''}" data-action="view" data-id="table">☷ Таблица</button></div>${permitted('orders',true)?'<button class="btn primary" data-action="new-order">+ Новый заказ</button>':''}</div></div>${filtersHTML()}<div id="order-results">${orderResults(list)}</div>`}
function orderResults(list){return view==='board'?`<div class="board" aria-label="Доска заказов">${state.stages.map((s,i)=>{let rows=list.filter(o=>o.status===i);return `<section class="column stage-${i}" data-stage="${i}"><div class="column-heading"><span class="status-dot"></span><h2>${s}</h2><span>${rows.length}</span></div><div class="column-total">${money(rows.reduce((a,o)=>a+o.amount,0))}</div><div class="column-cards">${rows.map(orderCard).join('')||'<div class="empty-column">Здесь пока нет заказов</div>'}</div></section>`}).join('')}</div>`:`<div class="table-wrap"><table><thead><tr>${[['id','Заказ'],['client','Клиент'],['course','Курс'],['amount','Сумма'],['status','Статус'],['paid','Оплата'],['manager','Менеджер'],['created','Создан']].map(([k,n])=>`<th><button data-action="sort" data-id="${k}">${n} ↕</button></th>`).join('')}</tr></thead><tbody>${list.map(o=>`<tr><td><button class="link" data-action="order" data-id="${o.id}">#${o.id}</button></td><td><strong>${esc(client(o).name)}</strong><small>${esc(client(o).email)}</small></td><td>${esc(course(o).title)}</td><td class="nowrap">${money(o.amount)}</td><td><span class="badge stage-${o.status}">${state.stages[o.status]}</span></td><td>${o.paid?'Оплачен':'Не оплачен'}</td><td>${esc(userName(o.manager))}</td><td class="nowrap">${date(o.created)}</td></tr>`).join('')||'<tr><td colspan="8" class="empty">Нет заказов по этим условиям. Измените фильтры.</td></tr>'}</tbody></table></div>`}
function renderCRM(){let allowed=Object.keys(labels).filter(k=>k==='employees'?state.user.role==='admin':permitted(k));if(!allowed.includes(section))section=allowed[0]||'none';app.innerHTML=`<div class="crm"><aside class="sidebar"><a class="brand" href="#" data-action="site">nutria<span><svg class="leaf-mark" viewBox="0 0 40 40" aria-hidden="true" focusable="false"><path d="M19 33C7 33 2 25 3 13c12-1 21 7 16 20Z" opacity=".75"/><path d="M22 26C16 13 24 4 37 3c1 13-4 23-15 23Z"/><path d="m12 23 12 13m-4-7 10-15" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg></span></a><div class="workspace"><span class="workspace-logo">n</span><div><strong>Онлайн-школа</strong><small>Демо-пространство</small></div><span class="live-dot"></span></div><div class="nav-label">Управление школой</div><nav>${allowed.map(k=>`<button class="${section===k?'selected':''}" data-action="section" data-id="${k}"><span>${icons[k]}</span>${labels[k]}${k==='orders'?`<small>${state.orders.length}</small>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="demo-tip"><span><svg class="leaf-mark" viewBox="0 0 40 40" aria-hidden="true" focusable="false"><path d="M19 33C7 33 2 25 3 13c12-1 21 7 16 20Z" opacity=".75"/><path d="M22 26C16 13 24 4 37 3c1 13-4 23-15 23Z"/><path d="m12 23 12 13m-4-7 10-15" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg></span><strong>Можно экспериментировать</strong><p>Изменения видны только вам. Все данные вымышлены.</p>${state.user.role==='admin'?'<button data-action="reset">Сбросить демо ↺</button>':''}</div><button data-action="site" class="back-site">↗ На сайт школы</button></div><div class="profile"><span class="avatar">${esc(state.user.name.split(' ').map(x=>x[0]).join(''))}</span><div><strong>${esc(state.user.name)}</strong><small>${state.user.role==='admin'?'Администратор':state.user.scope==='own'?'Менеджер · свои заказы':'Менеджер'}</small></div><button data-action="logout" title="Выйти" aria-label="Выйти">⇥</button></div></aside><div class="crm-main"><header class="crm-top"><span><i class="live-dot"></i> Школа в вашем ритме</span><div><span class="moscow">Время: Москва</span><button class="icon-btn" data-action="refresh" aria-label="Обновить данные" title="Обновить">↻</button><span class="avatar tiny">${esc(state.user.name[0])}</span></div></header><main class="crm-content">${section==='orders'?ordersHTML():section==='clients'?clientsHTML():section==='tasks'?tasksHTML():section==='courses'?coursesHTML():section==='analytics'?analyticsHTML():section==='employees'?employeesHTML():'<div class="empty"><h1>Нет доступных разделов</h1><p>Обратитесь к администратору для назначения прав.</p></div>'}</main><div class="crm-foot">NUTRIA CRM <span>Демонстрационные данные · Москва, UTC+3</span></div></div></div>`;if(state.user.mustChange)passwordModal()}
function clientsHTML(){return `<div class="page-title"><div><div class="breadcrumb">Рабочее пространство / Люди</div><h1>Клиенты <span class="count">${state.clients.length}</span></h1><p>История каждого знакомства — в одном месте.</p></div></div><label class="search standalone">⌕<input id="client-search" placeholder="Имя, email или телефон" aria-label="Найти клиента"></label><div class="people-grid">${state.clients.map(c=>`<button class="person-card" data-client-search="${esc([c.name,c.email,c.phone].join(' ').toLowerCase())}" data-action="client" data-id="${c.id}"><span class="avatar">${esc(c.name.split(' ').map(x=>x[0]).join(''))}</span><h3>${esc(c.name)}${c.archived?' · Архив':""}</h3><p>${esc(c.email)}</p><p>${esc(c.phone)}</p><div><span>${state.orders.filter(o=>o.clientId===c.id).length} заказов</span><strong>${money(state.orders.filter(o=>o.clientId===c.id&&o.paid).reduce((a,o)=>a+o.amount,0))}</strong></div></button>`).join('')}</div><p id="client-empty" class="empty" hidden>Клиенты не найдены. Измените запрос.</p>`}
function tasksHTML(){let tasks=state.tasks.filter(t=>taskTab==='all'||taskTab==='done'?taskTab==='done'?t.done:true:!t.done&&(taskTab==='today'?t.due===today():taskTab==='late'?t.due<today():t.due>today()));return `<div class="page-title"><div><div class="breadcrumb">Рабочее пространство / Планирование</div><h1>Задачи <span class="count">${tasks.length}</span></h1><p>Следующий шаг для каждого клиента.</p></div>${permitted('tasks',true)?'<button class="btn primary" data-action="new-task">+ Создать задачу</button>':''}</div><div class="tabs">${[['all','Все'],['today','Сегодня'],['future','Предстоящие'],['late','Просроченные'],['done','Выполненные']].map(([k,n])=>`<button class="${taskTab===k?'active':''}" data-action="task-tab" data-id="${k}">${n}</button>`).join('')}</div><div class="task-list">${tasks.map(t=>`<article class="task-row ${t.done?'done':''}"><input type="checkbox" aria-label="Выполнить: ${esc(t.title)}" data-task="${t.id}" ${t.done?'checked':''} ${permitted('tasks',true)?'':'disabled'}><div><h3>${esc(t.title)}</h3><p>${esc(t.description)}</p><button class="link" data-action="order" data-id="${t.orderId}">Заказ #${t.orderId}</button> · ${esc(userName(t.manager))}</div><span class="${!t.done&&t.due<today()?'overdue':''}">${t.due}${!t.done&&t.due<today()?'<small>Просрочено</small>':''}</span></article>`).join('')||'<div class="empty">В этом разделе пока нет задач.</div>'}</div>`}
function coursesHTML(){return `<div class="page-title"><div><div class="breadcrumb">Рабочее пространство / Обучение</div><h1>Курсы</h1><p>Программы школы и актуальная стоимость.</p></div></div><div class="crm-courses">${state.courses.map(c=>`<article><img src="${image(c.image,600)}" alt="${esc(c.title)}"><div><span class="muted">${c.weeks} ${c.weeks===4?'недели':'недель'}</span><h2>${esc(c.title)}</h2><p>${esc(c.desc)}</p><div class="course-bottom"><strong>${money(c.price)}</strong>${permitted('courses',true)?`<button class="btn outline" data-action="edit-course" data-id="${c.id}">Изменить</button>`:''}</div></div></article>`).join('')}</div>`}
function analyticsHTML(){let rows=filteredOrders(),paid=rows.filter(o=>o.paid),sum=paid.reduce((a,o)=>a+o.amount,0),total=rows.reduce((a,o)=>a+o.amount,0);return `<div class="page-title"><div><div class="breadcrumb">Рабочее пространство / Результаты</div><h1>Аналитика</h1><p>По дате создания заказа. Только доступные вам данные.</p></div></div>${filtersHTML()}<div class="metrics">${[['Новые заказы',rows.length],['Сумма заказов',money(total)],['Оплачено',money(sum)],['Конверсия в оплату',(rows.length?Math.round(paid.length/rows.length*100):0)+'%'],['Средний оплаченный заказ',money(paid.length?sum/paid.length:0)]].map(([n,v])=>`<article><span>${n}</span><strong>${v}</strong></article>`).join('')}</div><div class="charts"><section class="panel"><h2>Заказы по этапам</h2><p class="muted">Количество заказов в текущем статусе</p>${state.stages.map((s,i)=>{let n=rows.filter(o=>o.status===i).length;return `<div class="bar-row"><span>${s}</span><progress class="bar-track" value="${n}" max="${Math.max(rows.length,1)}" aria-label="${esc(s)}"></progress><strong>${n}</strong></div>`}).join('')}</section><section class="panel"><h2>Популярность курсов</h2><p class="muted">По количеству заказов за период</p>${state.courses.map(c=>`<div class="ranking"><div><strong>${esc(c.title)}</strong><small>${rows.filter(o=>o.courseId===c.id).length} заказов</small></div><span>${money(rows.filter(o=>o.courseId===c.id&&o.paid).reduce((a,o)=>a+o.amount,0))}</span></div>`).join('')}</section></div><section class="panel"><h2>Результаты менеджеров</h2><div class="table-wrap"><table><thead><tr><th>Менеджер</th><th>Заказы</th><th>Оплаченные</th><th>Сумма оплат</th></tr></thead><tbody>${state.users.filter(u=>rows.some(o=>o.manager===u.id)).map(u=>{let r=rows.filter(o=>o.manager===u.id);return `<tr><td>${esc(u.name)}</td><td>${r.length}</td><td>${r.filter(o=>o.paid).length}</td><td>${money(r.filter(o=>o.paid).reduce((a,o)=>a+o.amount,0))}</td></tr>`}).join('')}</tbody></table></div></section><p class="muted small">Конверсия = оплаченные заказы / все заказы, созданные в выбранном периоде. Оплата — демонстрационная.</p>`}
function employeesHTML(){return `<div class="page-title"><div><div class="breadcrumb">Рабочее пространство / Команда</div><h1>Сотрудники <span class="count">${state.users.length}</span></h1><p>Профили, область видимости и доступ к разделам.</p></div><button class="btn primary" data-action="employee">+ Добавить сотрудника</button></div><div class="people-grid">${state.users.map(u=>`<article class="person-card"><span class="avatar">${esc(u.name.split(' ').map(x=>x[0]).join(''))}</span><h3>${esc(u.name)}</h3><p>${esc(u.email)}</p><p>${esc(u.position)}</p><div><span class="badge">${u.blocked?'Заблокирован':u.role==='admin'?'Администратор':u.scope==='own'?'Свои заказы':'Все заказы'}</span>${u.id!==state.user.id?`<button class="link" data-action="employee" data-id="${u.id}">Настроить</button>`:''}</div></article>`).join('')}</div>`}
function orderModal(id){let o=state.orders.find(o=>o.id===Number(id));if(!o){toast('Заказ недоступен');return}let c=client(o),write=permitted('orders',true);modal(`<div class="quiet-label">Заказ #${o.id} · ${esc(o.source)}</div><h2>${esc(c.name)}</h2><p>${esc(course(o).title)}</p><div class="order-detail-grid"><section><div class="panel compact"><h3>Данные клиента</h3><p>${esc(c.email)}<br>${esc(c.phone||'Телефон не указан')}</p>${permitted('clients')?`<button class="link" data-action="client" data-id="${c.id}">Открыть профиль клиента</button>`:''}</div><form data-form="order"><input type="hidden" name="id" value="${o.id}"><label>Статус<select name="status" ${write?'':'disabled'}>${options(state.stages.map((s,i)=>[i,s]),o.status)}</select></label><label>Сумма, ₽<input type="number" min="0" step="0.01" name="amount" value="${o.amount/100}" ${write?'':'disabled'} required></label><label>Ответственный<select name="manager" ${state.user.role==='admin'?'':'disabled'}>${options(state.users.map(u=>[u.id,u.name]),o.manager)}</select></label><label class="checkbox"><input type="checkbox" name="paid" ${o.paid?'checked':''} ${write?'':'disabled'}>Оплата подтверждена (демо)</label><label>Причина отказа<textarea name="reason" ${write?'':'disabled'} placeholder="Обязательно при отказе">${esc(o.reason||'')}</textarea></label><p class="form-error" role="alert"></p>${write?'<button class="btn primary full">Сохранить изменения</button>':''}</form>${state.user.role==='admin'?`<button class="link spaced" data-action="archive-order" data-id="${o.id}">${o.archived?'Восстановить заказ':'Архивировать заказ'}</button>`:''}<p class="muted small">Создан: ${date(o.created)}<br>Изменён: ${date(o.updated)} · Москва</p></section><section><h3>Общение с клиентом</h3><div class="comment-list">${o.comments.map(c=>`<article class="comment"><strong>${esc(c.author)}</strong><time>${date(c.date)}</time><p>${esc(c.text)}</p></article>`).join('')||'<p class="muted">Комментариев пока нет.</p>'}</div>${write?`<form data-form="comment"><input type="hidden" name="id" value="${o.id}"><label>Новый комментарий<textarea required name="comment" maxlength="1000" placeholder="Что обсудили и о чём договорились?"></textarea></label><p class="form-error" role="alert"></p><button class="btn outline">Добавить комментарий</button></form>`:''}<h3 class="spaced">Следующий шаг</h3>${state.tasks.filter(t=>t.orderId===o.id).map(t=>`<p class="task-mini">${t.done?'✓':'◷'} ${esc(t.title)} <small>${t.due} · ${esc(userName(t.manager))}</small></p>`).join('')||'<p class="muted">Задач пока нет.</p>'}${permitted('tasks',true)?`<button class="link" data-action="new-task" data-id="${o.id}">+ Создать задачу</button>`:''}<h3 class="spaced">История изменений</h3><div class="timeline">${[...o.history].reverse().map(h=>`<article><strong>${esc(h.text)}</strong><small>${esc(h.author)} · ${date(h.date)}</small></article>`).join('')}</div></section></div>`,true)}
function clientModal(id){let c=state.clients.find(c=>c.id===id);if(!c)return;let rows=state.orders.filter(o=>o.clientId===id);modal(`<div class="quiet-label">Профиль клиента</div><h2>${esc(c.name)}</h2><form data-form="client"><input type="hidden" name="id" value="${c.id}"><label>Имя<input name="name" value="${esc(c.name)}" required ${permitted('clients',true)?'':'disabled'}></label><label>Email<input name="email" type="email" value="${esc(c.email)}" required ${permitted('clients',true)?'':'disabled'}></label><label>Телефон<input name="phone" value="${esc(c.phone)}" ${permitted('clients',true)?'':'disabled'}></label><p class="form-error" role="alert"></p>${permitted('clients',true)?'<button class="btn outline">Сохранить контакты</button>':''}</form>${state.user.role==='admin'?`<button class="link spaced" data-action="archive-client" data-id="${c.id}">${c.archived?'Восстановить клиента и заказы':'Архивировать клиента и заказы'}</button>`:''}<h3 class="spaced">Доступные заказы</h3>${rows.map(o=>`<button class="list-link" data-action="order" data-id="${o.id}"><span>#${o.id} · ${esc(course(o).title)}<small>${state.stages[o.status]}</small></span><strong>${money(o.amount)}</strong></button>`).join('')}<div class="checkout-summary"><span>Оплачено по доступным заказам</span><strong>${money(rows.filter(o=>o.paid).reduce((a,o)=>a+o.amount,0))}</strong></div>`)}
function taskModal(id=''){modal(`<h2>Следующий шаг.</h2><form data-form="task"><label>Заказ<select name="orderId" required>${options(state.orders.map(o=>[o.id,'#'+o.id+' · '+client(o).name]),id)}</select></label><label>Задача<input name="title" required maxlength="150" placeholder="Обсудить программу курса"></label><label>Описание<textarea name="description"></textarea></label><label>Срок<input name="due" type="date" required value="${today()}"></label><p class="muted small">Ответственный — менеджер выбранного заказа.</p><p class="form-error" role="alert"></p><button class="btn primary full">Создать задачу</button></form>`)}
function employeeModal(id){let u=state.users.find(u=>u.id===id);modal(`<div class="quiet-label">Управление доступом</div><h2>${u?'Профиль сотрудника':'Новый сотрудник'}</h2><form data-form="employee">${u?`<input type="hidden" name="id" value="${u.id}">`:''}<label>Имя<input name="name" required value="${esc(u?.name||'')}"></label><label>Email<input name="email" type="email" required value="${esc(u?.email||'')}" ${u?'readonly':''}></label><label>Должность<input name="position" value="${esc(u?.position||'Менеджер обучения')}"></label><label>${u?'Новый временный пароль (оставьте пустым, чтобы сохранить)':'Временный пароль'}<input name="password" type="password" minlength="10" ${u?'':'required'} autocomplete="new-password"></label><label>Область видимости<select name="scope">${options([['all','Все заказы'],['own','Только свои заказы']],u?.scope||'own')}</select></label><h3>Права на разделы</h3>${Object.keys(labels).filter(k=>k!=='employees').map(k=>`<label class="permission-row">${labels[k]}<select name="perm_${k}">${options([[0,'Нет доступа'],[1,'Просмотр'],...(k==='analytics'?[]:[[2,'Просмотр и изменение']])],u?.permissions[k]??(k==='analytics'?0:2))}</select></label>`).join('')}${u?`<label class="checkbox"><input type="checkbox" name="blocked" ${u.blocked?'checked':''}>Заблокировать профиль</label>`:''}<p class="notice">После изменения прав сотруднику потребуется войти снова. При новом временном пароле он должен будет его сменить.</p><p class="form-error" role="alert"></p><button class="btn primary full">Сохранить профиль</button></form>`)}
function passwordModal(){modal(`<h2>Измените временный пароль</h2><p>Перед началом работы установите свой пароль.</p><form data-form="password"><label>Новый пароль<input type="password" name="password" required minlength="10" autocomplete="new-password"></label><p class="form-error" role="alert"></p><button class="btn primary full">Сохранить и продолжить</button></form>`)}
document.addEventListener('click',async e=>{let el=e.target.closest('[data-action]');if(!el)return;let {action,id}=el.dataset;e.preventDefault();try{if(action==='close'){if(!state?.user.mustChange)close()}else if(action==='course')courseModal(id);else if(action==='checkout')checkout(id);else if(action==='login')login();else if(action==='demo'){el.disabled=true;try{await api('demo',{role:id});await enter()}catch(err){el.disabled=false;throw err}}else if(action==='site'){close();publicData=await api('public');site()}else if(action==='section'){section=id;query='';renderCRM()}else if(action==='view'){view=id;renderCRM()}else if(action==='archive-view'){showArchive=!showArchive;renderCRM()}else if(action==='archive-order'){await api('archive',{id:Number(id),archived:!state.orders.find(o=>o.id===Number(id)).archived});await enter();toast('Архив обновлён')}else if(action==='archive-client'){await api('archive',{entity:'client',id,archived:!state.clients.find(c=>c.id===id).archived});await enter();toast('Архив клиента обновлён')}else if(action==='order')orderModal(id);else if(action==='client')clientModal(id);else if(action==='new-task')taskModal(id);else if(action==='employee')employeeModal(id);else if(action==='new-order'){modal(`<h2>Новый заказ</h2><p>Добавьте заявку, полученную в разговоре с клиентом.</p><form data-form="new-order"><input type="hidden" name="key" value="${crypto.randomUUID()}"><label>Курс<select name="courseId">${options(state.courses.map(c=>[c.id,c.title+' · '+money(c.price)]),'')}</select></label><label>Имя клиента<input name="name" required></label><label>Email<input name="email" type="email" required placeholder="student@example.com"></label><label>Телефон<input name="phone" type="tel"></label><label>Комментарий<textarea name="comment"></textarea></label><p class="form-error" role="alert"></p><button class="btn primary full">Создать заказ</button></form>`)}else if(action==='logout'){await api('logout',{});state=null;publicData=await api('public');site();toast('Вы вышли из CRM')}else if(action==='refresh'){await enter();toast('Данные обновлены')}else if(action==='clear-filters'){query='';filters={status:'',manager:'',course:'',paid:'',from:'',to:''};renderCRM()}else if(action==='task-tab'){taskTab=id;renderCRM()}else if(action==='reset'){modal('<h2>Начать заново?</h2><p>Ваши изменения будут удалены. Другие посетители продолжат работу со своими данными.</p><button class="btn danger" data-action="confirm-reset">Сбросить моё демо</button>')}else if(action==='confirm-reset'){await api('reset',{});close();state=null;publicData=await api('public');site();toast('Демо восстановлено')}else if(action==='edit-course'){let c=state.courses.find(c=>c.id===Number(id));modal(`<h2>Настройки курса</h2><form data-form="course"><input type="hidden" name="id" value="${c.id}"><label>Название<input name="title" required value="${esc(c.title)}"></label><label>Стоимость, ₽<input name="price" type="number" min="0" step="0.01" required value="${c.price/100}"></label><label>Описание<textarea name="desc">${esc(c.desc)}</textarea></label><p class="form-error" role="alert"></p><button class="btn primary">Сохранить курс</button></form>`)}else if(action==='pay-success'||action==='pay-fail'){el.disabled=true;let p=await api('pay',{id:Number(el.dataset.order),token:el.dataset.token,success:action==='pay-success'});modal(`<div class="success-mark">${p.paid?'✓':'!'}</div><h2>${p.paid?'Демо-оплата прошла':'Оплата не прошла'}</h2><p>${p.paid?'Состояние оплаты обновлено в заказе.':'Списание не выполнялось. Заказ сохранён и ожидает оплаты.'}</p><button class="btn primary" data-action="login">Открыть CRM</button>`)}else if(action==='sort'){let key=id;window.sortAsc=window.sortKey===key?!window.sortAsc:true;window.sortKey=key;state.orders.sort((a,b)=>{let val=o=>key==='client'?client(o).name:key==='course'?course(o).title:key==='manager'?userName(o.manager):o[key];return String(val(a)).localeCompare(String(val(b)),'ru',{numeric:true})*(window.sortAsc?1:-1)});$('#order-results').innerHTML=orderResults(filteredOrders())}}catch(err){toast(err.message)}});
document.addEventListener('submit',async e=>{let f=e.target.closest('[data-form]');if(!f)return;e.preventDefault();let b=formData(f),button=f.querySelector('button[type="submit"],button:not([type])');if(button?.disabled)return;if(button)button.disabled=true;let error=f.querySelector('.form-error');if(error)error.textContent='';try{switch(f.dataset.form){case'login':await api('login',b);publicData=await api('public');if(publicData.user.mustChange){state={user:publicData.user};passwordModal()}else await enter();break;case'password':await api('password',b);await enter();break;case'new-order':{let r=await api('new-order',b);state=await api('state');renderCRM();orderModal(r.id);toast('Заказ создан');break}case'checkout':{let r=await api('checkout',{...b,consent:!!b.consent});modal(`<div class="success-mark">✓</div><div class="quiet-label">Заказ #${r.id}</div><h2>Первый шаг сделан.</h2><p>Заявка уже в вашей демо CRM. Попробуйте оплату или зайдите как менеджер и обработайте заказ.</p><p class="notice">Это имитация. Банковские реквизиты не нужны.</p><div class="stack"><button class="btn primary" data-action="pay-success" data-order="${r.id}" data-token="${r.paymentToken}">Имитировать успешную оплату</button><button class="btn outline" data-action="pay-fail" data-order="${r.id}" data-token="${r.paymentToken}">Имитировать ошибку оплаты</button><button class="text-button" data-action="login">Перейти в CRM ↗</button></div>`);break}case'order':{let id=b.id;let old=state.orders.find(o=>o.id===Number(id));await api('order',{id:Number(id),status:Number(b.status),amount:Math.round(Number(b.amount)*100),paid:!!b.paid,reason:b.reason,...(b.manager?{manager:b.manager}:{})});state=await api('state');renderCRM();orderModal(id);toast('Заказ сохранён');break}case'comment':await api('order',{id:Number(b.id),comment:b.comment});state=await api('state');renderCRM();orderModal(b.id);toast('Комментарий добавлен');break;case'task':await api('task',b);await enter();toast('Задача создана');break;case'client':await api('client',b);await enter();toast('Контакты сохранены');break;case'course':await api('course',{...b,id:Number(b.id),price:Math.round(Number(b.price)*100)});await enter();toast('Курс обновлён');break;case'employee':await api('employee',{...b,blocked:!!b.blocked,permissions:Object.fromEntries(Object.keys(labels).filter(k=>k!=='employees').map(k=>[k,Number(b['perm_'+k])]))});await enter();toast('Профиль сохранён');break}}catch(err){if(error)error.textContent=err.message;else toast(err.message)}finally{if(button)button.disabled=false}});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;if(section==='orders')$('#order-results').innerHTML=orderResults(filteredOrders());else{let focus=e.target.selectionStart;renderCRM();$('#search').focus();$('#search').setSelectionRange(focus,focus)}}if(e.target.id==='client-search'){let q=e.target.value.toLowerCase(),n=0;document.querySelectorAll('[data-client-search]').forEach(c=>{c.hidden=!c.dataset.clientSearch.includes(q);if(!c.hidden)n++});$('#client-empty').hidden=n>0}});
document.addEventListener('change',async e=>{if(e.target.dataset.filter){filters[e.target.dataset.filter]=e.target.value;if(section==='orders')$('#order-results').innerHTML=orderResults(filteredOrders());else renderCRM()}if(e.target.dataset.task){try{await api('task',{id:e.target.dataset.task,done:e.target.checked});state=await api('state');renderCRM();toast('Задача обновлена')}catch(err){e.target.checked=!e.target.checked;toast(err.message)}}});
let dragged=null;document.addEventListener('dragstart',e=>{let card=e.target.closest('[data-order]');if(card){dragged=Number(card.dataset.order);e.dataTransfer.setData('text/plain',String(dragged));card.classList.add('dragging')}});document.addEventListener('dragend',e=>{e.target.closest('[data-order]')?.classList.remove('dragging');document.querySelectorAll('.drop-over').forEach(x=>x.classList.remove('drop-over'))});document.addEventListener('dragover',e=>{let col=e.target.closest('[data-stage]');if(col&&dragged){e.preventDefault();col.classList.add('drop-over')}});document.addEventListener('dragleave',e=>{e.target.closest('[data-stage]')?.classList.remove('drop-over')});document.addEventListener('drop',async e=>{let col=e.target.closest('[data-stage]');if(!col||!dragged)return;e.preventDefault();let id=dragged,status=Number(col.dataset.stage);dragged=null;col.classList.remove('drop-over');let o=state.orders.find(o=>o.id===id);if(o.status===status)return;if(status===7||status===4&&!o.paid){orderModal(id);let f=mr.querySelector('[data-form="order"]');f.elements.status.value=String(status);toast(status===7?'Укажите причину отказа':'Подтвердите оплату и сохраните заказ');return}try{await api('order',{id,status});state=await api('state');renderCRM();toast('Статус обновлён')}catch(err){toast(err.message)}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!state?.user.mustChange)close();if(e.key==='Tab'&&mr.children.length){let nodes=[...mr.querySelectorAll('button,input,select,textarea,a[href]')].filter(n=>!n.disabled&&n.offsetParent);let first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
async function boot(){try{publicData=await api('public');site()}catch(err){app.innerHTML=`<div class="loading"><h1>Не удалось загрузить школу</h1><p>${esc(err.message)}</p><button class="btn primary" id="retry">Повторить</button></div>`;$('#retry').onclick=boot}}boot();










